// Adds the RCS chassis headers to the Keil MDK project generated by CubeMX.
// CubeMX's MDK exporter registers only .c files of a pack component and puts the
// header directory on the include path, so headers are invisible in the Keil tree.
// Idempotent: running it again after every CubeMX "Generate Code" is safe.
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text;
using System.Xml;
using System.Xml.Linq;
[assembly: AssemblyTitle("RCS Keil Header Fix")]
[assembly: AssemblyVersion("0.3.5.0")]
[assembly: AssemblyFileVersion("0.3.5.0")]
static class KeilHeaders {
 static readonly string[] Module={"rcs_chassis.h","rcs_control.h","rcs_hal.h"};
 static string Norm(string p){return p.Replace('\\','/').Trim();}
 static string Relative(string fromDir,string file){
  var from=new Uri(Path.GetFullPath(fromDir).TrimEnd('\\')+"\\");var to=new Uri(Path.GetFullPath(file));
  return Uri.UnescapeDataString(from.MakeRelativeUri(to).ToString()).Replace('\\','/');}
 static List<string> FindProjects(string arg){
  string p=Path.GetFullPath(String.IsNullOrWhiteSpace(arg)?Environment.CurrentDirectory:arg.Trim().Trim('"'));
  if(File.Exists(p)){
   if(p.EndsWith(".uvprojx",StringComparison.OrdinalIgnoreCase))return new List<string>{p};
   p=Path.GetDirectoryName(p);}
  if(!Directory.Exists(p))throw new Exception("路径不存在："+p);
  var found=new List<string>();
  foreach(string dir in new[]{p,Path.Combine(p,"MDK-ARM")})
   if(Directory.Exists(dir))found.AddRange(Directory.GetFiles(dir,"*.uvprojx"));
  return found.Distinct(StringComparer.OrdinalIgnoreCase).ToList();}
 internal static int Fix(string project,Action<string> say){
  string dir=Path.GetDirectoryName(project);
  var doc=XDocument.Load(project,LoadOptions.None);int added=0;bool anyGroup=false;
  foreach(var target in doc.Descendants("Target")){
   var include=target.Descendants("Cads").Elements("VariousControls").Elements("IncludePath").Select(e=>(string)e).FirstOrDefault()??"";
   foreach(var group in target.Descendants("Group")){
    var files=group.Element("Files");if(files==null)continue;
    var chassis=files.Elements("File").Select(f=>(string)f.Element("FilePath")).FirstOrDefault(f=>f!=null&&Norm(f).EndsWith("/rcs_chassis.c",StringComparison.OrdinalIgnoreCase));
    if(chassis==null)continue;anyGroup=true;
    string moduleDir=Path.GetDirectoryName(Path.GetFullPath(Path.Combine(dir,Norm(chassis))));
    var wanted=new List<string>();
    foreach(string h in Module){string full=Path.Combine(moduleDir,h);if(File.Exists(full))wanted.Add(full);}
    // rcs_config.h is rendered by CubeMX into Inc/ or Core/Inc/; locate it via the include path.
    foreach(string inc in include.Split(';').Select(Norm).Where(s=>s.Length>0)){
     string full=Path.GetFullPath(Path.Combine(dir,inc,"rcs_config.h"));
     if(File.Exists(full)){wanted.Add(full);break;}}
    var present=new HashSet<string>(files.Elements("File").Select(f=>(string)f.Element("FilePath")).Where(f=>f!=null).Select(f=>Path.GetFullPath(Path.Combine(dir,Norm(f)))),StringComparer.OrdinalIgnoreCase);
    foreach(string full in wanted){
     if(present.Contains(full))continue;
     files.Add(new XElement("File",new XElement("FileName",Path.GetFileName(full)),new XElement("FileType","5"),new XElement("FilePath",Relative(dir,full))));
     present.Add(full);added++;}
   }
  }
  if(!anyGroup)throw new Exception("工程中没有包含 rcs_chassis.c 的分组。请先在 CubeMX 中启用 RCS 底盘组件并 Generate Code："+project);
  if(added==0){say("已是最新，无需修改："+project);return 0;}
  string backup=project+".rcs-backup";if(!File.Exists(backup))File.Copy(project,backup);
  string temp=project+".rcs-tmp";
  var settings=new XmlWriterSettings{Encoding=new UTF8Encoding(false),Indent=true,IndentChars="  "};
  using(var w=XmlWriter.Create(temp,settings))doc.Save(w);
  File.Copy(temp,project,true);File.Delete(temp);
  say("已加入 "+added+" 个头文件到 Keil 工程："+project+"（Keil 已打开时请选择重新加载工程）");
  return 0;}
 static int Main(string[] args){
  Console.OutputEncoding=new UTF8Encoding(false);
  string postLog=null;
  try{
#if RCS_POSTGEN
   string toolDir=Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location);
   postLog=Path.Combine(toolDir,"headers-result.txt");
   string root=Path.GetDirectoryName(toolDir);
   var projects=FindProjects(root);
#else
   var projects=FindProjects(args.Length>0?args[0]:null);
#endif
   if(projects.Count==0)throw new Exception("未找到 .uvprojx。请传入 CubeMX 工程目录、.ioc 文件或 .uvprojx 文件。");
   var messages=new List<string>();foreach(var p in projects)Fix(p,s=>{messages.Add(s);Console.WriteLine(s);});
   if(postLog!=null)File.WriteAllText(postLog,"PASS "+DateTime.UtcNow.ToString("o")+"\r\n"+String.Join("\r\n",messages.ToArray()),new UTF8Encoding(false));
   return 0;
  }catch(Exception e){if(postLog!=null)File.WriteAllText(postLog,"FAIL "+DateTime.UtcNow.ToString("o")+"\r\n"+e.Message,new UTF8Encoding(false));Console.Error.WriteLine("失败："+e.Message);return 2;}
 }
}
